package glitch

import data.glitch_lib

insecure_protocol_patterns := {"ftp://", "http://", "telnet://", "smtp://", "pop://", "imap://", "gopher://", "tftp://"}

int_check_attrs := {"checksum", "sha256", "sha512", "md5", "hash", "integrity", "gpgcheck", "verify_checksum", "check_signature", "verify", "checksum_mode", "checksum_algorithm", "expected_checksum", "sha1", "sha224", "sha384", "sha256sum", "md5sum", "gpg_key", "key", "signature", "validate_certs", "ssl_verify", "verify_ssl"}

disable_verify_attrs := {"verify_ssl", "validate_certs", "ssl_verify", "insecure", "ssl_verify_mode", "verify_peer", "validate", "strict", "verify_mode", "tls"}

url_attrs := {"url", "source", "src", "download_url", "uri", "baseurl", "mirrorlist", "repository", "base_url", "src_url", "file", "oracle_url", "download"}

is_insecure_protocol(str) {
    pattern := insecure_protocol_patterns[_]
    startswith(lower(str), pattern)
}

has_insecure_protocol_in_any_string(node) {
    walk(node, [_, n])
    n.ir_type == "String"
    is_insecure_protocol(n.value)
}

has_insecure_protocol_in_any_string(node) {
    walk(node, [_, n])
    n.ir_type == "VariableReference"
    is_insecure_protocol(n.value)
}

is_disabled_value(val_node) {
    val_node.ir_type == "Boolean"
    val_node.value == false
}

is_disabled_value(val_node) {
    val_node.ir_type == "Integer"
    val_node.value == 0
}

is_disabled_value(val_node) {
    val_node.ir_type == "String"
    lower(val_node.value) == "false"
}

is_disabled_value(val_node) {
    val_node.ir_type == "String"
    lower(val_node.value) == "no"
}

is_disabled_value(val_node) {
    val_node.ir_type == "String"
    lower(val_node.value) == "off"
}

find_disabled_key_anywhere(root, key_names) {
    walk(root, [_, child])
    child.ir_type == "KeyValue"
    child.name == key_names[_]
    is_disabled_value(child.value)
}

find_disabled_key_anywhere(root, key_names) {
    walk(root, [_, child])
    child.ir_type == "Attribute"
    child.name == key_names[_]
    is_disabled_value(child.value)
}

is_remote_or_download_op(node) {
    node.type == "remote_file"
}

is_remote_or_download_op(node) {
    node.type == "get_url"
}

is_remote_or_download_op(node) {
    node.type == "fetch"
}

is_remote_or_download_op(node) {
    node.type == "archive"
}

is_remote_or_download_op(node) {
    node.type == "download"
}

is_remote_or_download_op(node) {
    node.type == "uri"
}

is_remote_or_download_op(node) {
    node.type == "s3_file"
}

is_remote_or_download_op(node) {
    node.type == "yum_repository"
}

is_remote_or_download_op(node) {
    node.type == "apt_repository"
}

is_remote_or_download_op(node) {
    node.type == "zypper_repository"
}

is_remote_or_download_op(node) {
    lower(node.type) == "package"
}

is_remote_or_download_op(node) {
    lower(node.type) == "template"
}

is_remote_or_download_op(node) {
    lower(node.type) == "file"
}

has_url_with_insecure_protocol_deep(root) {
    walk(root, [_, child])
    child.ir_type == "KeyValue"
    child.name == url_attrs[_]
    has_insecure_protocol_in_any_string(child.value)
}

has_url_with_insecure_protocol_deep(root) {
    walk(root, [_, child])
    child.ir_type == "Attribute"
    child.name == url_attrs[_]
    has_insecure_protocol_in_any_string(child.value)
}

