  case $::kernel {
    'Linux' : {
      case $::operatingsystem {
        'CentOS' : {
          # Oracle Java 6 comes in a special rpmbin format
          if $version == '6' {
            $package_type = 'rpmbin'
          } else {
            $package_type = 'rpm'
          }
        }
        default : {
          fail ("unsupported platform ${::operatingsystem}") }
      }

      $os = 'linux'
      $destination_dir = '/tmp/'
      $creates_path = "/usr/java/${install_path}"
    }
    default : {
      fail ( "unsupported platform ${::kernel}" ) }
  }

