find_disabled_in_structure(root, key_names) {
    walk(root, [_, child])
    child.ir_type == "KeyValue"
    some key_name
    key_name == key_names[_]
    child.name == key_name
    is_disabled_value(child.value)
}

find_disabled_in_structure(root, key_names) {
    walk(root, [_, child])
    child.ir_type == "Attribute"
    some key_name
    key_name == key_names[_]
    child.name == key_name
    is_disabled_value(child.value)
}

find_disabled_in_structure(root, key_names) {
    walk(root, [_, child])
    child.ir_type == "Hash"
    walk(child.value, [_, kv])
    kv.ir_type == "KeyValue"
    some key_name
    key_name == key_names[_]
    kv.name == key_name
    is_disabled_value(kv.value)
}

has_insecure_url_in_structure(root) {
    walk(root, [_, child])
    child.ir_type == "KeyValue"
    some url_attr
    url_attr == {"url", "source", "src", "download_url", "uri", "baseurl", "mirrorlist", "repository", "base_url", "src_url", "file", "download", "archive_url", "package_url"}[_]
    child.name == url_attr
    has_insecure_protocol_in_any_string(child.value)
}

has_insecure_url_in_structure(root) {
