has_source_or_url_attr(node) {
    walk(node, [_, child])
    child.ir_type == "Attribute"
    some url_attr
    url_attr == {"url", "source", "src", "download_url", "uri", "baseurl", "mirrorlist", "repository", "base_url", "src_url", "oracle_url"}[_]
