has_suspicious_source_pattern(node) {
    walk(node, [_, n])
    n.ir_type == "CodeElement"
    n.code != null
    code_lower := lower(n.code)
    contains(code_lower, "new_resource.url")
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    walk(parent, [_, var])
    var.ir_type == "Variable"
    find_disabled_in_structure(var, int_check_attrs)

    result := {
        "type": "sec_no_int_check",
        "element": var,
        "path": parent.path,
        "description": "Missing support for integrity check - Variable contains disabled integrity verification configuration. (CWE-353)"
    }
}

